+import { readFileSync } from "node:fs";
+import path from "node:path";
+import { parseTasks } from "./tasks.ts";
+import { planOrder } from "./planner.ts";
+import { TaskPlanError } from "./errors.ts";
+
+const USAGE = "Usage: node src/cli.ts plan <file.json> [--json]";
+
+function printUsageAndExit(code: number): never {
+  process.stderr.write(USAGE + "\n");
+  process.exit(code);
+}
+
+function main(): void {
+  const args = process.argv.slice(2);
+  if (args.length === 0 || args[0] !== "plan") {
+    process.stderr.write(USAGE + "\n");
+    process.exit(2);
+  }
+  const rest = args.slice(1);
+  // Count --json
+  let jsonCount = 0;
+  for (const a of rest) if (a === "--json") jsonCount++;
+  if (jsonCount > 1) {
+    process.stderr.write(USAGE + "\n");
+    process.exit(2);
+  }
+  const jsonMode = jsonCount === 1;
+  // unknown options
+  for (const a of rest) {
+    if (a.startsWith("-") && a !== "--json") {
+      process.stderr.write(USAGE + "\n");
+      process.exit(2);
+    }
+  }
+  const files = rest.filter((a) => a !== "--json");
+  if (files.length !== 1) {
+    process.stderr.write(USAGE + "\n");
+    process.exit(2);
+  }
+  const fileArg = files[0]!;
+  const resolved = path.resolve(process.cwd(), fileArg);
+  let content: string;
+  try {
+    content = readFileSync(resolved, "utf8");
+  } catch (e) {
+    const msg = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error: ${msg}\n` + USAGE + "\n");
+    process.exit(2);
+  }
+  let json: unknown;
+  try {
+    json = JSON.parse(content);
+  } catch (e) {
+    const msg = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error INVALID_JSON: ${msg}\n`);
+    process.exit(1);
+  }
+  let tasks;
+  try {
+    tasks = parseTasks(json);
+  } catch (e) {
+    if (e instanceof TaskPlanError) {
+      const msg = e.message;
+      process.stderr.write(`error ${e.code}: ${msg}\n`);
+      process.exit(1);
+    }
+    throw e;
+  }
+  let result;
+  try {
+    result = planOrder(tasks);
+  } catch (e) {
+    if (e instanceof TaskPlanError) {
+      const msg = e.message;
+      process.stderr.write(`error ${e.code}: ${msg}\n`);
+      process.exit(1);
+    }
+    throw e;
+  }
+
+  if (jsonMode) {
+    process.stdout.write(JSON.stringify({ order: result.order, stages: result.stages }) + "\n");
+  } else {
+    let out = "";
+    if (result.stages.length === 0) {
+      out = "Order:\n";
+    } else {
+      for (let i = 0; i < result.stages.length; i++) {
+        out += `Stage ${i + 1}: ${result.stages[i]!.join(", ")}\n`;
+      }
+      out += `Order: ${result.order.join(", ")}\n`;
+    }
+    process.stdout.write(out);
+  }
+}
+
+main();
