+import { TaskPlanError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of planning tasks in dependency order. */
+export interface PlanResult {
+  /** Every task id, in execution order. */
+  order: string[];
+  /** stages[k]: the tasks that can run at the earliest in round k. */
+  stages: string[][];
+}
+
+/** Thrown when two or more tasks share the same id. */
+export class DuplicateTaskError extends TaskPlanError {
+  /** Every id that occurs more than once, each once, ordered by first position. */
+  readonly taskIds: string[];
+  constructor(taskIds: string[], message?: string) {
+    super("DUPLICATE_ID", message ?? `duplicate task ids: ${taskIds.join(", ")}`);
+    this.taskIds = taskIds;
+  }
+}
+
+/** Thrown when a task depends on an unknown id. */
+export class UnknownDependencyError extends TaskPlanError {
+  /** The task that has the missing dependency. */
+  readonly taskId: string;
+  /** The missing id. */
+  readonly dependency: string;
+  constructor(taskId: string, dependency: string, message?: string) {
+    super("UNKNOWN_DEPENDENCY", message ?? `task ${taskId} depends on unknown ${dependency}`);
+    this.taskId = taskId;
+    this.dependency = dependency;
+  }
+}
+
+/** Thrown when the dependency graph contains a cycle. */
+export class CycleError extends TaskPlanError {
+  /** A closed path: first and last ids are equal, each id depends on the next. */
+  readonly cycle: string[];
+  constructor(cycle: string[], message?: string) {
+    super("CYCLE", message ?? `cycle: ${cycle.join(" -> ")}`);
+    this.cycle = cycle;
+  }
+}
+
+/**
+ * Plans tasks in dependency order.
+ *
+ * Validates duplicates, unknown dependencies and cycles (in that order),
+ * then returns an execution order and stages.
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  // Duplicate ids check
+  const firstPos = new Map<string, number>();
+  const counts = new Map<string, number>();
+  for (let i = 0; i < tasks.length; i++) {
+    const id = tasks[i]!.id;
+    if (!firstPos.has(id)) firstPos.set(id, i);
+    counts.set(id, (counts.get(id) ?? 0) + 1);
+  }
+  const duplicates: { id: string; pos: number }[] = [];
+  for (const [id, cnt] of counts) {
+    if (cnt > 1) duplicates.push({ id, pos: firstPos.get(id)! });
+  }
+  if (duplicates.length > 0) {
+    duplicates.sort((a, b) => a.pos - b.pos);
+    throw new DuplicateTaskError(duplicates.map((d) => d.id));
+  }
+
+  // Unknown dependency check
+  const idSet = new Set<string>();
+  for (const t of tasks) idSet.add(t.id);
+  for (const t of tasks) {
+    for (const dep of t.dependsOn) {
+      if (!idSet.has(dep)) {
+        throw new UnknownDependencyError(t.id, dep);
+      }
+    }
+  }
+
+  if (tasks.length === 0) return { order: [], stages: [] };
+
+  // Build deduped adjacency and reverse adjacency
+  const n = tasks.length;
+  const idToIndex = new Map<string, number>();
+  for (let i = 0; i < n; i++) idToIndex.set(tasks[i]!.id, i);
+
+  const adj: string[][] = new Array<string[]>(n);
+  // dedup deps per task
+  for (let i = 0; i < n; i++) {
+    const deps = tasks[i]!.dependsOn;
+    const seen = new Set<string>();
+    const uniq: string[] = [];
+    for (const d of deps) {
+      if (!seen.has(d)) {
+        seen.add(d);
+        uniq.push(d);
+      }
+    }
+    adj[i] = uniq;
+  }
+
+  // Cycle detection (iterative DFS)
+  const state = new Uint8Array(n); // 0 unvisited, 1 visiting, 2 done
+  const posMap = new Map<string, number>(); // id -> position in path stack
+  const pathStack: string[] = [];
+  const stack: { idx: number; nextDep: number }[] = [];
+
+  for (let start = 0; start < n; start++) {
+    if ((state[start] as number) !== 0) continue;
+    stack.push({ idx: start, nextDep: 0 });
+    state[start] = 1;
+    pathStack.push(tasks[start]!.id);
+    posMap.set(tasks[start]!.id, pathStack.length - 1);
+
+    while (stack.length > 0) {
+      const frame = stack[stack.length - 1]!;
+      const deps = adj[frame.idx]!;
+      if (frame.nextDep < deps.length) {
+        const neighId = deps[frame.nextDep]!;
+        frame.nextDep++;
+        const neighIdx = idToIndex.get(neighId)!;
+        const st = state[neighIdx] as number;
+        if (st === 0) {
+          state[neighIdx] = 1;
+          stack.push({ idx: neighIdx, nextDep: 0 });
+          pathStack.push(neighId);
+          posMap.set(neighId, pathStack.length - 1);
+        } else if (st === 1) {
+          const idxInPath = posMap.get(neighId)!;
+          const slice = pathStack.slice(idxInPath);
+          // slice is [neighId ... current frame id]
+          const cycle = [...slice, neighId];
+          throw new CycleError(cycle);
+        } else {
+          // done, ignore
+        }
+      } else {
+        // finish node
+        state[frame.idx] = 2;
+        const poppedId = pathStack.pop()!;
+        posMap.delete(poppedId);
+        stack.pop();
+      }
+    }
+  }
+
+  // Compute order with priority heap
+  // indegree = number of unique deps
+  const indeg = new Int32Array(n);
+  for (let i = 0; i < n; i++) indeg[i] = adj[i]!.length;
+
+  // dependents reverse adjacency
+  const dependents: number[][] = Array.from({ length: n }, () => []);
+  for (let i = 0; i < n; i++) {
+    for (const depId of adj[i]!) {
+      const depIdx = idToIndex.get(depId)!;
+      dependents[depIdx]!.push(i);
+    }
+  }
+
+  // heap for ready tasks
+  const heap: number[] = [];
+  const compare = (a: number, b: number): number => {
+    const pa = tasks[a]!.priority;
+    const pb = tasks[b]!.priority;
+    if (pa !== pb) return (pb as number) - (pa as number); // higher priority first
+    return a - b; // earlier input first
+  };
+  // heap invariant: parent better (smaller compare) than children
+  function heapPush(v: number): void {
+    heap.push(v);
+    let i = heap.length - 1;
+    while (i > 0) {
+      const p = (i - 1) >> 1;
+      if (compare(heap[i]!, heap[p]!) < 0) {
+        const tmp: number = heap[i]!;
+        heap[i] = heap[p]!;
+        heap[p] = tmp;
+        i = p;
+      } else break;
+    }
+  }
+  function heapPop(): number | undefined {
+    if (heap.length === 0) return undefined;
+    const top: number = heap[0]!;
+    const last: number = heap.pop()!;
+    if (heap.length > 0) {
+      heap[0] = last;
+      let i = 0;
+      while (true) {
+        const l = i * 2 + 1;
+        const r = l + 1;
+        let best = i;
+        if (l < heap.length && compare(heap[l]!, heap[best]!) < 0) best = l;
+        if (r < heap.length && compare(heap[r]!, heap[best]!) < 0) best = r;
+        if (best !== i) {
+          const tmp: number = heap[i]!;
+          heap[i] = heap[best]!;
+          heap[best] = tmp;
+          i = best;
+        } else break;
+      }
+    }
+    return top;
+  }
+
+  for (let i = 0; i < n; i++) if ((indeg[i]! as number) === 0) heapPush(i);
+
+  const orderIdx: number[] = [];
+  while (heap.length > 0) {
+    const cur = heapPop()!;
+    orderIdx.push(cur);
+    const deps = dependents[cur]!;
+    for (const dep of deps) {
+      indeg[dep] = indeg[dep]! - 1;
+      if ((indeg[dep]! as number) === 0) heapPush(dep);
+    }
+  }
+
+  const order = orderIdx.map((i) => tasks[i]!.id);
+
+  // Compute stages rounds
+  const round = new Int32Array(n);
+  for (const idx of orderIdx) {
+    const deps = adj[idx]!;
+    if (deps.length === 0) {
+      round[idx] = 0;
+    } else {
+      let maxR = -1;
+      for (const depId of deps) {
+        const depIdx = idToIndex.get(depId)!;
+        const r: number = round[depIdx]! as number;
+        if (r > maxR) maxR = r;
+      }
+      round[idx] = maxR + 1;
+    }
+  }
+  let maxRound = -1;
+  for (let i = 0; i < n; i++) if ((round[i]! as number) > maxRound) maxRound = round[i]! as number;
+  const stages: string[][] = maxRound >= 0 ? Array.from({ length: maxRound + 1 }, () => [] as string[]) : [];
+  const stageIndices: number[][] = maxRound >= 0 ? Array.from({ length: maxRound + 1 }, () => [] as number[]) : [];
+  for (let i = 0; i < n; i++) {
+    const r = round[i]! as number;
+    stageIndices[r]!.push(i);
+  }
+  for (let r = 0; r < stageIndices.length; r++) {
+    const arr = stageIndices[r]!;
+    arr.sort((a, b) => {
+      const pa = tasks[a]!.priority;
+      const pb = tasks[b]!.priority;
+      if (pa !== pb) return (pb as number) - (pa as number);
+      return a - b;
+    });
+    stages[r] = arr.map((i) => tasks[i]!.id);
+  }
+
+  return { order, stages };
+}
